#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 200005

int P[MAXN];
int left_greater[MAXN], left_second_greater[MAXN];
int right_greater[MAXN], right_second_greater[MAXN];
int stack[MAXN];
int n;

void compute_left() {
    int top = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && P[stack[top]] < P[i])
            top--;
        left_greater[i] = (top >= 0) ? stack[top] : -1;
        if (top >= 1)
            left_second_greater[i] = stack[top - 1];
        else
            left_second_greater[i] = -1;
        stack[++top] = i;
    }
}

void compute_right() {
    int top = -1;
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && P[stack[top]] < P[i])
            top--;
        right_greater[i] = (top >= 0) ? stack[top] : n;
        if (top >= 1)
            right_second_greater[i] = stack[top - 1];
        else
            right_second_greater[i] = n;
        stack[++top] = i;
    }
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d", &P[i]);

    compute_left();
    compute_right();

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        int L1 = left_greater[i];
        int L2 = left_second_greater[i];
        int R1 = right_greater[i];
        int R2 = right_second_greater[i];

        long long left_count = L1 - L2;
        long long right_count = R2 - R1;
        ans += (long long)P[i] * left_count * right_count;

        left_count = R1 - i;
        right_count = i - L1;
        ans += (long long)P[i] * left_count * right_count;
    }

    printf("%lld\n", ans);
    return 0;
}

