    for(int i=1;i<=n;i++) cin>>p[i];
    vector<int> L(n+2,0),R(n+2,n+1),LL(n+2,0),RR(n+2,n+1);
    stack<int> st;
    for(int i=1;i<=n;i++){while(!st.empty()&&p[st.top()]<p[i]){R[st.top()]=i;st.pop();}st.push(i);}
    while(!st.empty())st.pop();
    for(int i=n;i>=1;i--){while(!st.empty()&&p[st.top()]<p[i]){L[st.top()]=i;st.pop();}st.push(i);}
    while(!st.empty())st.pop();
    // LL[i] = left boundary for left[i]
    for(int i=1;i<=n;i++) if(L[i]) LL[i]=L[L[i]]; else LL[i]=0;
    for(int i=1;i<=n;i++) if(R[i]<=n) RR[i]=R[R[i]]; else RR[i]=n+1;
    long long ans=0;
    for(int i=1;i<=n;i++){
        int l=L[i],r=R[i];
        long long ll2=(l?LL[i]:0), rr2=(r<=n?RR[i]:n+1);
        // only left: L in (ll2, l], R in [i, r-1)
        if(l) ans+=p[i]*(long long)(l-ll2)*(r-i);
        // only right: L in (l, i], R in [r, rr2)  wait
        // L in (l,i] means L>l so left greater not included, R in [r, rr2-1]
        if(r<=n) ans+=p[i]*(long long)(i-l)*(rr2-r);
    }
    cout<<ans<<endl;
