using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> P(N + 1), pos(N + 1);
    for (int i = 1; i <= N; i++) {
        cin >> P[i];
        pos[P[i]] = i;
    }

    // Maintain positions of values already processed, i.e. values > current x.
    // For current x, these are exactly the positions of elements larger than x.
    // To make x the second maximum in a subarray, the subarray must contain
    // exactly one such larger element.
    //
    // Let the larger positions around pos[x] be:
    // l2 < l1 < pos[x] < r1 < r2
    // (using sentinels 0,0 and N+1,N+1 when missing)
    //
    // Then the number of subarrays where the unique larger element is at l1:
    //   choose L in (l2, l1], R in [pos[x], r1)
    // count = (l1 - l2) * (r1 - pos[x])
    //
    // Similarly, if the unique larger element is at r1:
    //   choose L in (l1, pos[x]], R in [r1, r2)
    // count = (pos[x] - l1) * (r2 - r1)

    set<int> s;
    s.insert(0);
    s.insert(0);
    s.insert(N + 1);
    s.insert(N + 1);

    long long ans = 0;

    for (int x = N; x >= 1; x--) {
        int p = pos[x];

        auto itR1 = s.lower_bound(p);
        int r1 = *itR1;
        int r2 = *next(itR1);

        auto itL1 = prev(itR1);
        int l1 = *itL1;
        int l2 = *prev(itL1);

        long long cntLeftGreater = 1LL * (l1 - l2) * (r1 - p);
        long long cntRightGreater = 1LL * (p - l1) * (r2 - r1);

        ans += 1LL * x * (cntLeftGreater + cntRightGreater);

        s.insert(p);
    }

    cout << ans << '\n';
    return 0;
}

