public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        int[] P = new int[N];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            P[i] = Integer.parseInt(st.nextToken());
        }

        // left greater
        int[] left = new int[N];
        int[] left2 = new int[N];
        Arrays.fill(left, -1);
        Arrays.fill(left2, -1);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < N; i++) {
            while (!stack.isEmpty() && P[stack.peek()] < P[i]) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                left[i] = stack.peek();
                stack.pop();
                if (!stack.isEmpty()) {
                    left2[i] = stack.peek();
                }
                stack.push(left[i]);
            }
            stack.push(i);
        }

        // right greater
        int[] right = new int[N];
        int[] right2 = new int[N];
        Arrays.fill(right, N);
        Arrays.fill(right2, N);
        stack.clear();
        for (int i = N - 1; i >= 0; i--) {
            while (!stack.isEmpty() && P[stack.peek()] < P[i]) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                right[i] = stack.peek();
                stack.pop();
                if (!stack.isEmpty()) {
                    right2[i] = stack.peek();
                }
                stack.push(right[i]);
            }
            stack.push(i);
        }

        long total = 0;
        for (int i = 0; i < N; i++) {
            long count = 0;
            // case: larger element on left
            if (left[i] != -1) {
                long lCount = left[i] - (left2[i] == -1 ? -1 : left2[i]);
                long rCount = (right[i] == N ? N : right[i]) - i;
                count += lCount * rCount;
            }
            // case: larger element on right
            if (right[i] != N) {
                long lCount = i - (left[i] == -1 ? -1 : left[i]);
                long rCount = (right2[i] == N ? N : right2[i]) - right[i];
                count += lCount * rCount;
            }
            total += count * P[i];
        }
        System.out.println(total);
    }
}

