        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        long[] p = new long[n+1];
        for(int i=1;i<=n;i++) p[i]=Long.parseLong(st.nextToken());
        int[] left=new int[n+2], right=new int[n+2];
        Deque<Integer> stack=new ArrayDeque<>();
        for(int i=1;i<=n;i++){left[i]=0;} 
        for(int i=1;i<=n;i++){while(!stack.isEmpty()&&p[stack.peek()]<p[i])stack.pop();left[i]=stack.isEmpty()?0:stack.peek();stack.push(i);}
        stack.clear();
        for(int i=n;i>=1;i--){while(!stack.isEmpty()&&p[stack.peek()]<p[i])stack.pop();right[i]=stack.isEmpty()?n+1:stack.peek();stack.push(i);}
        long ans=0;
        for(int i=1;i<=n;i++){
            int l=left[i],r=right[i];
            // max is at l: L in (left[l], l], R in [i, r-1] but l must be in range => L<=l, already. count = (l - left[l]) * (r - i)
            if(l>0) ans+=p[i]*(long)(l-left[l])*(r-i);
            // max is at r: L in (l, i], R in [r, right[r]-1). count=(i-l)*(right[r]-r)
            if(r<=n) ans+=p[i]*(long)(i-l)*(right[r]-r);
        }
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int[] pos = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            int p = fs.nextInt();
            pos[p] = i;
        }

        TreeSet<Integer> set = new TreeSet<>();
        set.add(0);
        set.add(0);
        set.add(N + 1);
        set.add(N + 1);

        long ans = 0;

        for (int x = N; x >= 1; x--) {
            int i = pos[x];

            Integer r1 = set.higher(i);
            Integer r2 = set.higher(r1);
            Integer l1 = set.lower(i);
            Integer l2 = set.lower(l1);

            long leftCount = l1 - l2;
            long midLeft = i - l1;
            long midRight = r1 - i;
            long rightCount = r2 - r1;

            ans += (long) x * (leftCount * midRight + midLeft * rightCount);

            set.add(i);
        }

        System.out.println(ans);
    }
}
